const trade = $input.first().json;
const currentPrice = parseFloat(trade.current_price || trade.entry_price);
const sl    = parseFloat(trade.sl);
const target = parseFloat(trade.current_target);
const entry = parseFloat(trade.entry_price);
const step  = parseFloat((entry * parseFloat(trade.trailing_pct || 0.5) / 100).toFixed(2));
const count = parseInt(trade.target_count || 0);

// Build trailing summary
const lockedProfit = parseFloat((sl - entry).toFixed(2));
const lockedPct    = parseFloat(((lockedProfit / entry) * 100).toFixed(4));

return [{
  json: {
    ...trade,
    step,
    locked_profit: lockedProfit,
    locked_pct: lockedPct,
    next_target: parseFloat((target + step).toFixed(2)),
    trail_level: count,
    summary: `Trail Level ${count} — SL locked at ₹${sl} (+${lockedPct}%) | Next target: ₹${target}`
  }
}];
